import assert from "node:assert/strict";
import { createHash } from "node:crypto";
import { gunzipSync } from "node:zlib";
// Immutable historical migration evidence only. Never read current App or Git in CI.
// cb original metrics + actual Git2cf literal operands + all104 original negative recipes.
const encoded =
  "";
const bytes = gunzipSync(Buffer.from(encoded, "base64"));
assert.equal(
  createHash("sha256").update(bytes).digest("hex"),
  "6768914185acdae224f2425323d107f53a46960798893e8c181a1c6265e254aa",
);
type HistoricalSource = {
  commit: string;
  path: string;
  bytes: number;
  sha256: string;
  gzipBase64: string;
};
export const navigationGovernanceArchive = JSON.parse(bytes.toString()) as {
  sources: Record<string, HistoricalSource>;
  originalGate: {
    commit: string;
    sha256: string;
    ledgerSha256: string;
    literalLedger: string;
  };
  ledger: Array<{
    id: number;
    group: number;
    index: number;
    title: string;
    changes: Record<string, Array<{ from: string; to: string }>>;
    originalPredicate: string;
    originalMessage: string | null;
    currentRule: string | null;
    handoff: string;
    reason: string;
  }>;
};
export function historicalNavigationSource(name: string) {
  const value = navigationGovernanceArchive.sources[name];
  assert.ok(value);
  const data = gunzipSync(Buffer.from(value.gzipBase64, "base64"));
  assert.equal(data.length, value.bytes);
  assert.equal(createHash("sha256").update(data).digest("hex"), value.sha256);
  return data.toString();
}
